\"use client\";

import { useState } from \"react\";
import { useTranslation } from \"react-i18next\";
import { downloadMyDataAction } from \"../actions\";
import { Button } from \"@/modules/ui/components/button\";

export const DownloadMyDataButton = () => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);

  const handleDownload = async () => {
    setLoading(true);
    try {
      const result = await downloadMyDataAction();
      if (result.success && result.data) {
        const json = JSON.stringify(result.data, null, 2);
        const blob = new Blob([json], { type: \"application/json\" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement(\"a\");
        a.href = url;
        a.download = \"formbricks-user-data.json\";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <Button variant=\"outline\" loading={loading} onClick={handleDownload}>
      {t(\"workspace.settings.profile.download_my_data\")}
    </Button>
  );
};
COMPONENT
echo \"Done\""

